public class Sortieren {

	public static void main(String[] args) {

		int[] a = {99, 0, 33, 27, 87, 80, 65, 77, 39, 88};

		System.out.println("Zu sortierendes Array:");
		for(int i = 0; i < a.length; i++){
			System.out.print(a[i] + " "); 
		}

		System.out.println("");
		sortieren(a);

		System.out.println("Sortiertes Array:");
		for(int i = 0; i < a.length; i++){
			System.out.print(a[i] + " ");
		}

	}

	static void sortiere(int[] a, int begin, int end) {

		if(begin < end) {
			int x = a[(begin + end) / 2];
		}


	}

	static void sortieren(int[] array) {

		int length = array.length;

		if(length <= 1) return;

		int middle = length / 2;

		int [] linkeArray = new int[middle];
		int [] rechteArray = new int[length - middle];

		int i = 0; //linke array
		int j = 0; //rechte Array

		for (; i < length; i++) {
			if(i < middle) {
				linkeArray[i] = array[i];
			}
			else {
				rechteArray[j] = array[j];
				j++;
			}
		}
		sortieren(linkeArray);
		sortieren(rechteArray);
		merage(linkeArray, rechteArray, array);
	}

	static void merage(int [] linkeArray, int [] rechteArray, int [] array) {

		int linkesize = array.length /2;
		int rechtesize = array.length - linkesize;

		int i = 0, l = 0, r = 0;

		while (l < linkesize && r < rechtesize) {
			if(linkeArray[l] < rechteArray[r]) {
				array[i] = linkeArray[l];
				i++;
				l++;
			}
			else {
				array[i] = rechteArray[r];
				i++;
				r++;
			}
		}
		while (l < linkesize) {
			array[i] = linkeArray[l];
			i++;
			l++;
		}
		while (r < rechtesize) {
			array[i] = rechteArray[r];
			i++;
			r++;
		}
	}
}

