        Scanner sc = new Scanner(System.in);
        int total;
        
        System.out.println("enter the total marks of all subjects");
        total = sc.nextInt();

        float math, english, science, hindi, social_studies;
        System.out.println("Enter the math marks: ");
        math = sc.nextFloat();
        System.out.println("Enter the english marks: ");
        english = sc.nextFloat();
        System.out.println("Enter the science marks: ");
        science = sc.nextFloat();
        System.out.println("Enter the hindi marks: ");
        hindi = sc.nextFloat();
        System.out.println("Enter the social studies: ");
        social_studies = sc.nextFloat();

        System.out.println("Total marks: " + total);
        
        float obtain;
        obtain = math + english + science + hindi + social_studies;
        System.out.println("total obtain marks: " + obtain);

        System.out.println("Math marks: " + math);
        System.out.println("percentage in maths: " + (math/(total/5))*100);

        System.out.println("English marks: " + english);
        System.out.println("percentage in english : " + (english/(total/5)*100));

        System.out.println("Science marks: " + science);
        System.out.println("percentage in science : " + (science/(total))*100);

        System.out.println("Hindi marks: " + hindi);
        System.out.println("percentage in hindi : " + (hindi/(total))*100);

        System.out.println("Social studies: " + social_studies);
        System.out.println("percentage in social science : " + (social_studies/(total/5))*100);

        System.out.println("overall percentage: " + obtain*100/total);


    }
}

