My solution for stopwatch problem using setInterval-

function StopWatch() {
  let time = 0;
  let id = null;
  this.start = function () {
    if (id) {
        // throw error
      console.log("cannot start again Try stop first");  
    } else {
      id = setInterval(() => {
        time += 0.1;
      }, 100);
    }
  };
  this.duration = function () {
    console.log(time);
  };
  this.stop = function () {
        // throw error
    if (!id) console.log("cannot stop again Try start first");
    else {
      clearInterval(id);
      id = null;
    }
  };
  this.reset = function () {
    if (id) {
        clearInterval(id)
    };
    id = null;
    time = 0;
  };
}

