class Solution:
    def findMin(self, nums: List[int]) -> int:
        l = 0
        r = len(nums) - 1

        # Find the position where nums[i - 1] > nums[i]
        while True:
            if nums[l] <= nums[r]:
                return nums[l]

            pivot = l + (r + 1 - l) // 2

            # if the value to the left is greater, return nums[pivot]
            if nums[pivot - 1] > nums[pivot]:
                return nums[pivot]

            # Decide which direction to go
            if nums[pivot] > nums[-1]:
                l = pivot
            else:
                r = pivot

