class Solution:

    def generateParenthesis(self, n: int) -> List[str]:
        res = []

        def backtrack(open, close, subResult):
            if open == close == n:
                res.append(subResult)
                return

            if open < n:
                backtrack(open + 1, close, subResult + '(')
            if close < open:
                backtrack(open, close + 1, subResult + ')')

        backtrack(0, 0, '')
        return res

